"""
Metadata-Filtered & Relevance-Ranked RAG System
================================================

A self-contained (Python standard-library only) Retrieval-Augmented
Generation (RAG) system that uses document *metadata* for two purposes:

1. FILTERING: candidate chunks are narrowed to those whose metadata matches
   a query-time filter (e.g. category, department, priority range, tags).
2. RANKING: results are ranked by relevance to the user query (dense
   hashed-embedding cosine similarity + BM25 lexical match), and can be
   further re-ranked with *metadata boost rules* (e.g. give official,
   high-priority sources a score lift).

Components
----------
- tokenize / STOPWORDS          : light text normalization
- HashingEmbedding              : TF-signed feature hashing -> dense vectors
- BM25                         : sparse lexical scorer (k1, b)
- RecursiveChunker              : structure-aware splitting with overlap
- MetadataFilter                : expression language over metadata fields
- BoostRule                     : metadata rules that add ranking weight
- MetadataIndex                 : stores chunks, embeddings, BM25 stats
- RAGGenerator                  : grounded prompt builder + optional LLM
- MetadataRAG                   : end-to-end pipeline (add -> index -> ask)
- evaluate_retrieval / ndcg_at_k: retrieval quality metrics

No third-party dependencies are required; plug any callable into
RAGGenerator(llm=...) to use a real LLM (e.g. an OpenAI client method).

Quick start
-----------
    from rag_metadata_system import MetadataRAG

    rag = MetadataRAG()
    rag.add_documents([
        {"text": "...", "metadata": {"category": "guides", "priority": 4}},
    ])
    rag.build_index()

    results = rag.retrieve(
        "chunk size recommendations",
        k=5,
        filters={"category": "guides"},
        boost_rules=[{"field": "priority", "op": "gte", "value": 4,
                      "weight": 0.5}],
    )
    answer = rag.ask("What chunk size should I use?", k=5,
                     filters={"category": "guides"})

Run the demo:
    python rag_metadata_system.py
"""

from __future__ import annotations

import hashlib
import json
import math
import re
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Sequence, Union

__all__ = [
    "MetadataRAG",
    "MetadataIndex",
    "MetadataFilter",
    "BoostRule",
    "BM25",
    "HashingEmbedding",
    "RecursiveChunker",
    "RAGGenerator",
    "Document",
    "Chunk",
    "RankedResult",
    "GeneratedAnswer",
    "evaluate_retrieval",
    "ndcg_at_k",
    "tokenize",
]

# ---------------------------------------------------------------------------
# Tokenization
# ---------------------------------------------------------------------------

STOPWORDS = frozenset(
    """
    a an and are as at be but by for from has have how i if in into is it its
    not of on or such that the their then there these they this to was we what
    when where which who will with you your
    """.split()
)


def tokenize(text: str) -> List[str]:
    """Lowercase, split on non-alphanumerics, drop stopwords and 1-char tokens."""
    if not text:
        return []
    raw = re.findall(r"[a-z0-9']+", text.lower())
    return [t for t in raw if t not in STOPWORDS and len(t) > 1]


def _stable_hash(token: str, seed: int = 0) -> int:
    """Deterministic (cross-run stable) integer hash for feature hashing."""
    digest = hashlib.md5(f"{seed}:{token}".encode("utf-8")).hexdigest()
    return int(digest, 16)


# ---------------------------------------------------------------------------
# Dense embeddings (feature hashing; no external model needed)
# ---------------------------------------------------------------------------


class HashingEmbedding:
    """TF-signed feature-hashing embedder.

    Each token maps deterministically to an index in ``dim`` dimensions with
    a sign.  Vectors are L2-normalized so the dot product is a cosine
    similarity.  This gives a dependency-free dense retriever; swap it for a
    real embedding model (OpenAI, sentence-transformers, ...) by subclassing
    or duck-typing ``embed(tokens) -> List[float]``.
    """

    def __init__(self, dim: int = 512):
        if dim <= 0:
            raise ValueError("embedding dimension must be positive")
        self.dim = dim

    def embed(self, tokens: Sequence[str]) -> List[float]:
        vec = [0.0] * self.dim
        for tok in tokens:
            h = _stable_hash(tok)
            idx = h % self.dim
            sign = 1.0 if (h >> 32) & 1 else -1.0
            vec[idx] += sign
        norm = math.sqrt(sum(v * v for v in vec))
        if norm > 0:
            vec = [v / norm for v in vec]
        return vec

    @staticmethod
    def cosine(a: Sequence[float], b: Sequence[float]) -> float:
        """Dot product of two normalized vectors == cosine similarity."""
        return sum(x * y for x, y in zip(a, b))


# ---------------------------------------------------------------------------
# BM25 sparse scorer
# ---------------------------------------------------------------------------


class BM25:
    """Classic BM25 lexical scorer (Robertson & Zaragoza variant)."""

    def __init__(self, k1: float = 1.5, b: float = 0.75):
        self.k1 = k1
        self.b = b
        self.doc_count: int = 0
        self.avg_dl: float = 0.0
        self.doc_freq: Dict[str, int] = {}
        self.doc_len: List[int] = []
        self.term_freqs: List[Dict[str, int]] = []

    def fit(self, tokenized_docs: Sequence[Sequence[str]]) -> None:
        self.doc_count = len(tokenized_docs)
        self.doc_len = [len(d) for d in tokenized_docs]
        self.avg_dl = sum(self.doc_len) / max(1, self.doc_count)
        self.term_freqs = []
        for doc in tokenized_docs:
            tf: Dict[str, int] = {}
            for tok in doc:
                tf[tok] = tf.get(tok, 0) + 1
            self.term_freqs.append(tf)
            for tok in set(doc):
                self.doc_freq[tok] = self.doc_freq.get(tok, 0) + 1

    def idf(self, term: str) -> float:
        df = self.doc_freq.get(term, 0)
        return math.log(1.0 + (self.doc_count - df + 0.5) / (df + 0.5))

    def score_doc(self, query_tokens: Sequence[str], doc_idx: int) -> float:
        dl = self.doc_len[doc_idx]
        tf_map = self.term_freqs[doc_idx]
        score = 0.0
        for term in set(query_tokens):
            tf = tf_map.get(term, 0)
            if tf == 0:
                continue
            denom = tf + self.k1 * (1.0 - self.b + self.b * dl / max(1e-9, self.avg_dl))
            score += self.idf(term) * (tf * (self.k1 + 1.0)) / denom
        return score


# ---------------------------------------------------------------------------
# Data types
# ---------------------------------------------------------------------------


@dataclass
class Document:
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    id: Optional[str] = None


@dataclass
class Chunk:
    text: str
    metadata: Dict[str, Any]
    doc_id: str
    chunk_index: int


@dataclass
class RankedResult:
    chunk: Chunk
    score: float
    dense_score: float
    sparse_score: float
    boost: float

    def to_dict(self, preview: int = 160) -> Dict[str, Any]:
        return {
            "doc_id": self.chunk.doc_id,
            "chunk_index": self.chunk.chunk_index,
            "metadata": self.chunk.metadata,
            "text": self.chunk.text[:preview] + ("..." if len(self.chunk.text) > preview else ""),
            "score": round(self.score, 4),
            "dense_score": round(self.dense_score, 4),
            "sparse_score": round(self.sparse_score, 4),
            "boost": round(self.boost, 4),
        }


@dataclass
class GeneratedAnswer:
    answer: str
    prompt: str
    sources: List[Dict[str, Any]]
    used_llm: bool


# ---------------------------------------------------------------------------
# Recursive chunker
# ---------------------------------------------------------------------------


class RecursiveChunker:
    """Splits a document into overlapping chunks.

    Splitting tries structure-aware separators in order (paragraphs, newlines,
    sentences, spaces) before falling back to hard character splits.  Chunk
    metadata inherits the source document's metadata and gains ``doc_id``,
    ``chunk_index``, and ``source`` fields.
    """

    def __init__(
        self,
        chunk_size: int = 600,
        chunk_overlap: int = 80,
        separators: Sequence[str] = ("\n\n", "\n", ". ", " "),
    ):
        if chunk_size <= 0 or chunk_overlap < 0 or chunk_overlap >= chunk_size:
            raise ValueError("need 0 <= chunk_overlap < chunk_size")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = tuple(separators)

    # -- splitting internals -------------------------------------------------

    @classmethod
    def _split_recursive(cls, text: str, seps: Sequence[str], idx: int,
                         chunk_size: int) -> List[str]:
        if len(text) <= chunk_size:
            return [text] if text.strip() else []
        if idx >= len(seps):
            # Hard character-level fallback.
            return [
                text[i:i + chunk_size]
                for i in range(0, len(text), chunk_size)
                if text[i:i + chunk_size].strip()
            ]
        sep = seps[idx]
        out: List[str] = []
        for piece in text.split(sep):
            piece = piece.strip()
            if not piece:
                continue
            # Re-attach the separator so sentence/paragraph breaks survive.
            piece = piece + sep
            if len(piece) <= chunk_size:
                out.append(piece)
            else:
                out.extend(cls._split_recursive(piece, seps, idx + 1, chunk_size))
        return out

    @staticmethod
    def _overlap_tail(text: str, n: int) -> str:
        if n <= 0 or len(text) <= n:
            return ""
        tail = text[-n:]
        if tail[0].isalnum():
            cut = tail.find(" ")
            if cut != -1:
                tail = tail[cut + 1:]
        return tail.lstrip()

    # -- public API ----------------------------------------------------------

    def split_document(self, doc: Document) -> List[Chunk]:
        pieces = self._split_recursive(doc.text, self.separators, 0, self.chunk_size)
        merged: List[str] = []
        buffer = ""
        for piece in pieces:
            if not buffer:
                buffer = piece
            elif len(buffer) + len(piece) <= self.chunk_size:
                buffer = buffer + piece
            else:
                merged.append(buffer.strip())
                buffer = self._overlap_tail(buffer, self.chunk_overlap) + piece
        if buffer.strip():
            merged.append(buffer.strip())

        chunks: List[Chunk] = []
        for i, text in enumerate(merged):
            meta = dict(doc.metadata)
            meta["doc_id"] = doc.id
            meta["chunk_index"] = i
            meta.setdefault("source", doc.id)
            chunks.append(
                Chunk(text=text, metadata=meta, doc_id=doc.id, chunk_index=i)
            )
        return chunks


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------

_OPS = frozenset(
    {"$eq", "$ne", "$in", "$nin", "$gt", "$gte", "$lt", "$lte",
     "$exists", "$contains", "$regex"}
)


def _values_equal(actual: Any, cond: Any) -> bool:
    """Equality that understands lists on either side (membership)."""
    if isinstance(actual, list):
        if isinstance(cond, list):
            return actual == cond
        return cond in actual
    if isinstance(cond, list):
        return actual in cond
    return actual == cond


def _contains(container: Any, item: Any) -> bool:
    if isinstance(container, list):
        return item in container
    if isinstance(container, str):
        return str(item) in container
    return False


class MetadataFilter:
    """Declarative metadata filter.

    Examples
    --------
    {"category": "guides"}                          # equality
    {"priority": {"$gte": 4, "$lt": 10}}            # range
    {"tags": {"$in": ["rag", "chunking"]}}          # list membership
    {"department": {"$ne": "hr"}}                   # negation
    {"year": {"$exists": True}}                     # presence
    {"title": {"$regex": "chunk.*size"}}            # regex
    {"tags": {"$contains": "rag"}}                  # list contains value
    {"$or": [{"category": "faq"}, {"priority": {"$gte": 5}}]}
    {"$and": [{"category": "guides"}, {"department": "engineering"}]}
    """

    def __init__(self, spec: Optional[Dict[str, Any]] = None):
        self.spec = spec or {}

    @staticmethod
    def _match_field(actual: Any, cond: Any) -> bool:
        if isinstance(cond, dict) and any(k in _OPS for k in cond):
            for op, expected in cond.items():
                if op not in _OPS:
                    raise ValueError(f"unsupported filter operator: {op!r}")
                if op == "$eq":
                    if not _values_equal(actual, expected):
                        return False
                elif op == "$ne":
                    if _values_equal(actual, expected):
                        return False
                elif op == "$in":
                    if not _contains(expected, actual):
                        return False
                elif op == "$nin":
                    if _contains(expected, actual):
                        return False
                elif op == "$gt":
                    if actual is None or not (actual > expected):
                        return False
                elif op == "$gte":
                    if actual is None or not (actual >= expected):
                        return False
                elif op == "$lt":
                    if actual is None or not (actual < expected):
                        return False
                elif op == "$lte":
                    if actual is None or not (actual <= expected):
                        return False
                elif op == "$exists":
                    if bool(expected) != (actual is not None):
                        return False
                elif op == "$contains":
                    if not _contains(actual, expected):
                        return False
                elif op == "$regex":
                    if not re.search(expected, str(actual or "")):
                        return False
            return True
        return _values_equal(actual, cond)

    def matches(self, metadata: Dict[str, Any]) -> bool:
        # AND clauses
        for clause in self.spec.get("$and", []):
            if not MetadataFilter(clause).matches(metadata):
                return False
        # OR clauses (combined with any remaining top-level fields)
        or_clauses = self.spec.get("$or")
        if or_clauses is not None:
            rest = {k: v for k, v in self.spec.items() if k not in ("$and", "$or")}
            for clause in or_clauses:
                if MetadataFilter({**rest, **clause}).matches(metadata):
                    return True
            return False
        # Plain field constraints
        for field_name, cond in self.spec.items():
            if field_name in ("$and", "$or"):
                continue
            if not self._match_field(metadata.get(field_name), cond):
                return False
        return True


# ---------------------------------------------------------------------------
# Metadata boost rules (affect ranking)
# ---------------------------------------------------------------------------


@dataclass
class BoostRule:
    """A metadata rule that adds ``weight`` to a chunk's ranking score when
    the chunk's metadata satisfies ``{field: {op: value}}``.

    Example: {"field": "priority", "op": "$gte", "value": 4, "weight": 0.5}
    """

    field: str
    op: str = "$eq"
    value: Any = None
    weight: float = 0.25

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "BoostRule":
        return cls(
            field=d["field"],
            op=d.get("op", "$eq"),
            value=d.get("value"),
            weight=float(d.get("weight", 0.25)),
        )

    def applies(self, metadata: Dict[str, Any]) -> bool:
        return MetadataFilter({self.field: {self.op: self.value}}).matches(metadata)


# ---------------------------------------------------------------------------
# Index + hybrid retrieval
# ---------------------------------------------------------------------------


class MetadataIndex:
    """Chunk store with hybrid dense/sparse retrieval, metadata filtering,
    and metadata-based ranking boosts."""

    def __init__(
        self,
        embedding: Optional[HashingEmbedding] = None,
        bm25: Optional[BM25] = None,
        dense_weight: float = 1.0,
        sparse_weight: float = 1.0,
    ):
        self.embedding = embedding or HashingEmbedding()
        self.bm25 = bm25 or BM25()
        self.dense_weight = dense_weight
        self.sparse_weight = sparse_weight
        self.chunks: List[Chunk] = []
        self._vecs: List[List[float]] = []
        self._built = False

    # -- indexing ------------------------------------------------------------

    def add_chunk(self, chunk: Chunk) -> None:
        self.chunks.append(chunk)
        self._built = False

    def build(self) -> None:
        token_lists = [tokenize(c.text) for c in self.chunks]
        self.bm25.fit(token_lists)
        self._vecs = [self.embedding.embed(tokens) for tokens in token_lists]
        self._built = True

    # -- retrieval -----------------------------------------------------------

    def retrieve(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Dict[str, Any]] = None,
        boost_rules: Optional[Sequence[Union[Dict[str, Any], BoostRule]]] = None,
    ) -> List[RankedResult]:
        if not self._built:
            self.build()
        if k <= 0:
            return []

        filt = MetadataFilter(filters)
        rules = [
            r if isinstance(r, BoostRule) else BoostRule.from_dict(r)
            for r in (boost_rules or [])
        ]

        qtokens = tokenize(query)
        qvec = self.embedding.embed(qtokens)

        # 1) FILTER: metadata narrows the candidate pool before scoring.
        candidates = [
            i for i in range(len(self.chunks))
            if filt.matches(self.chunks[i].metadata)
        ]
        if not candidates:
            return []

        # 2) RANK: score each candidate by query relevance (dense + sparse),
        #    normalized per query so the two signals are comparable.
        dense = [HashingEmbedding.cosine(qvec, self._vecs[i]) for i in candidates]
        sparse = [self.bm25.score_doc(qtokens, i) for i in candidates]
        max_d = max(dense) or 1.0
        max_s = max(sparse) or 1.0

        scored: List[RankedResult] = []
        for j, i in enumerate(candidates):
            d = dense[j] / max_d
            s = sparse[j] / max_s
            relevance = self.dense_weight * d + self.sparse_weight * s
            # 3) RANKING: metadata boost rules add weight on top of relevance.
            boost = sum(r.weight for r in rules if r.applies(self.chunks[i].metadata))
            scored.append(
                RankedResult(
                    chunk=self.chunks[i],
                    score=relevance + boost,
                    dense_score=d,
                    sparse_score=s,
                    boost=boost,
                )
            )

        scored.sort(key=lambda r: r.score, reverse=True)
        return scored[:k]


# ---------------------------------------------------------------------------
# Generation
# ---------------------------------------------------------------------------

DEFAULT_PROMPT_TEMPLATE = """You are a helpful assistant that answers strictly from the provided context.

Context:
{context}

Question: {question}

Rules:
- Answer only using the context above.
- Cite sources as [1], [2], ... after each claim.
- If the context does not contain the answer, reply exactly: "I don't have enough information."

Answer:"""


class RAGGenerator:
    """Builds a grounded prompt from retrieved chunks and produces an answer.

    Pass ``llm`` (a ``Callable[[str], str]`` that maps a prompt to a response)
    to use a real model.  Without one, a deterministic extractive fallback
    answers from the top retrieved sentences with source citations.
    """

    def __init__(
        self,
        llm: Optional[Callable[[str], str]] = None,
        prompt_template: str = DEFAULT_PROMPT_TEMPLATE,
    ):
        self.llm = llm
        self.prompt_template = prompt_template

    def build_context(self, results: Sequence[RankedResult],
                      max_chars: int = 6000) -> str:
        parts: List[str] = []
        used = 0
        for i, r in enumerate(results, start=1):
            meta = {k: v for k, v in r.chunk.metadata.items()}
            header = (
                f"[{i}] doc_id={r.chunk.doc_id} chunk={r.chunk.chunk_index} "
                f"score={r.score:.3f} metadata={json.dumps(meta, default=str)}"
            )
            block = f"{header}\n{r.chunk.text}"
            if used + len(block) > max_chars and parts:
                break
            parts.append(block)
            used += len(block)
        return "\n\n".join(parts)

    @staticmethod
    def _source_dict(r: RankedResult) -> Dict[str, Any]:
        return {
            "doc_id": r.chunk.doc_id,
            "chunk_index": r.chunk.chunk_index,
            "metadata": r.chunk.metadata,
            "score": round(r.score, 4),
            "text": r.chunk.text,
        }

    def _extractive_answer(self, query: str,
                           results: Sequence[RankedResult]) -> str:
        if not results:
            return "I don't have enough information in the indexed documents."
        qtokens = set(tokenize(query))
        best: List[Tuple[str, RankedResult]] = []
        for r in results[:2]:
            for sent in re.split(r"(?<=[.!?])\s+", r.chunk.text):
                s = sent.strip()
                if not s:
                    continue
                overlap = len(qtokens & set(tokenize(s)))
                if overlap > 0:
                    best.append((overlap, s, r))
        if best:
            best.sort(key=lambda x: -x[0])
            seen = set()
            chosen: List[Tuple[str, RankedResult]] = []
            for _, s, r in best:
                key = (r.chunk.doc_id, r.chunk.chunk_index)
                if key in seen:
                    continue
                seen.add(key)
                chosen.append((s, r))
                if len(chosen) >= 2:
                    break
            answer = " ".join(
                s + f" [doc {r.chunk.doc_id} · chunk {r.chunk.chunk_index}]"
                for s, r in chosen
            )
        else:
            r = results[0]
            answer = (
                r.chunk.text[:300].strip()
                + f" [doc {r.chunk.doc_id} · chunk {r.chunk.chunk_index}]"
            )
        return (
            answer
            + "\n\n(extractive fallback answer; pass an `llm` callable to "
              "RAGGenerator for full generation.)"
        )

    def generate(self, query: str,
                 results: Sequence[RankedResult]) -> GeneratedAnswer:
        context = self.build_context(results)
        prompt = self.prompt_template.format(context=context, question=query)
        if self.llm is not None:
            answer = self.llm(prompt)
            used_llm = True
        else:
            answer = self._extractive_answer(query, results)
            used_llm = False
        sources = [self._source_dict(r) for r in results]
        return GeneratedAnswer(
            answer=answer, prompt=prompt, sources=sources, used_llm=used_llm
        )


# ---------------------------------------------------------------------------
# End-to-end pipeline
# ---------------------------------------------------------------------------


class MetadataRAG:
    """High-level RAG pipeline.

    add_documents -> build_index -> retrieve / ask
    """

    def __init__(
        self,
        chunker: Optional[RecursiveChunker] = None,
        embedding: Optional[HashingEmbedding] = None,
        index: Optional[MetadataIndex] = None,
        generator: Optional[RAGGenerator] = None,
        dense_weight: float = 1.0,
        sparse_weight: float = 1.0,
    ):
        self.chunker = chunker or RecursiveChunker()
        self.embedding = embedding
        self.generator = generator or RAGGenerator()
        self.index = index or MetadataIndex(
            embedding=self.embedding,
            dense_weight=dense_weight,
            sparse_weight=sparse_weight,
        )
        self.documents: List[Document] = []

    def add_documents(
        self, documents: Sequence[Union[Document, Dict[str, Any]]]
    ) -> None:
        for d in documents:
            if isinstance(d, Document):
                doc = d
            else:
                doc = Document(
                    text=d["text"],
                    metadata=dict(d.get("metadata", {})),
                    id=d.get("id"),
                )
            if not doc.id:
                doc.id = f"doc-{len(self.documents) + 1}"
            self.documents.append(doc)
            for chunk in self.chunker.split_document(doc):
                self.index.add_chunk(chunk)

    def build_index(self) -> None:
        self.index.build()

    def retrieve(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Dict[str, Any]] = None,
        boost_rules: Optional[Sequence[Union[Dict[str, Any], BoostRule]]] = None,
    ) -> List[RankedResult]:
        return self.index.retrieve(
            query, k=k, filters=filters, boost_rules=boost_rules
        )

    def ask(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Dict[str, Any]] = None,
        boost_rules: Optional[Sequence[Union[Dict[str, Any], BoostRule]]] = None,
    ) -> Dict[str, Any]:
        results = self.retrieve(query, k=k, filters=filters,
                                boost_rules=boost_rules)
        gen = self.generator.generate(query, results)
        return {
            "answer": gen.answer,
            "prompt": gen.prompt,
            "sources": gen.sources,
            "used_llm": gen.used_llm,
            "results": results,
        }


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------


def ndcg_at_k(relevance: Sequence[int], k: int) -> float:
    """Normalized discounted cumulative gain at k (binary relevance)."""
    k = min(k, len(relevance))
    dcg = sum(rel / math.log2(i + 2) for i, rel in enumerate(relevance[:k]))
    ideal = sorted(relevance, reverse=True)[:k]
    idcg = sum(rel / math.log2(i + 2) for i, rel in enumerate(ideal))
    return dcg / idcg if idcg > 0 else 0.0


def evaluate_retrieval(
    rag: MetadataRAG,
    query_items: Sequence[Tuple[str, Sequence[str]]],
    k: int = 5,
    filters: Optional[Dict[str, Any]] = None,
    boost_rules: Optional[Sequence[Union[Dict[str, Any], BoostRule]]] = None,
) -> Dict[str, float]:
    """Retrieval quality over ground-truth query -> relevant doc-id pairs.

    Returns mean precision@k, recall@k, nDCG@k and the mean number of
    results actually returned.
    """
    precisions: List[float] = []
    recalls: List[float] = []
    ndcgs: List[float] = []
    counts: List[int] = []
    for query, relevant in query_items:
        results = rag.retrieve(query, k=k, filters=filters,
                               boost_rules=boost_rules)
        retrieved_ids = [r.chunk.doc_id for r in results]
        relevant_set = set(relevant)
        hit = len(set(retrieved_ids) & relevant_set)
        counts.append(len(results))
        precisions.append(hit / max(1, len(retrieved_ids)))
        recalls.append(hit / max(1, len(relevant_set)))
        rel = [1 if rid in relevant_set else 0 for rid in retrieved_ids]
        ndcgs.append(ndcg_at_k(rel, k))
    return {
        "precision_at_k": sum(precisions) / len(precisions) if precisions else 0.0,
        "recall_at_k": sum(recalls) / len(recalls) if recalls else 0.0,
        "ndcg_at_k": sum(ndcgs) / len(ndcgs) if ndcgs else 0.0,
        "mean_results": sum(counts) / len(counts) if counts else 0.0,
    }


# ---------------------------------------------------------------------------
# Demo
# ---------------------------------------------------------------------------


def _demo() -> None:
    print("=" * 78)
    print("Metadata-Filtered & Relevance-Ranked RAG System — demo")
    print("=" * 78)

    rag = MetadataRAG(chunker=RecursiveChunker(chunk_size=400, chunk_overlap=60))

