class RankedResult:
    chunk: Chunk
    score: float
    dense_score: float
    sparse_score: float
    boost: float

    def to_dict(self, preview: int = 160) -> Dict[str, Any]:
        return {
            "doc_id": self.chunk.doc_id,
            "chunk_index": self.chunk.chunk_index,
            "metadata": self.chunk.metadata,
            "text": self.chunk.text[:preview] + ("..." if len(self.chunk.text) > preview else ""),
            "score": round(self.score, 4),
            "dense_score": round(self.dense_score, 4),
            "sparse_score": round(self.sparse_score, 4),
            "boost": round(self.boost, 4),
        }


