                "query-document pairs directly."
            ),
            "metadata": {
                "category": "guides", "department": "engineering",
                "priority": 4, "year": 2024, "source": "official",
                "tags": ["retrieval", "reranking"],
            },
        },
        {
            "text": (
                "Q: What is RAG? A: Retrieval augmented generation grounds LLM "
                "answers in external documents retrieved at query time. Q: Do I "
                "need a GPU to run this demo? A: No, the reference "
                "implementation uses hashed embeddings and BM25. Q: How do I "
                "add metadata? A: Pass a metadata dictionary per document "
                "before indexing."
            ),
            "metadata": {
                "category": "faq", "department": "hr",
                "priority": 1, "year": 2023, "source": "official",
                "tags": ["onboarding"],
            },
        },
    ]

    rag.add_documents(docs)
    rag.build_index()
    print(f"\nIndexed {len(rag.documents)} documents, "
          f"{len(rag.index.chunks)} chunks.\n")

    # 1) Baseline relevance ranking (no filter, no boost)
    q1 = "what chunk size should I use for document splitting"
    print("-" * 78)
    print(f"QUERY (baseline): {q1!r}")
    for r in rag.retrieve(q1, k=3):
        d = r.to_dict()
        print(f"  score={d['score']:.3f} dense={d['dense_score']:.3f} "
              f"sparse={d['sparse_score']:.3f} | doc={d['doc_id']} "
              f"cat={d['metadata'].get('category')} "
              f"priority={d['metadata'].get('priority')}")

    # 2) Metadata FILTERING narrows the candidate pool
    print("-" * 78)
    q2 = "how do I measure retrieval quality"
    print(f"QUERY (filtered category='guides'): {q2!r}")
    filtered = rag.retrieve(q2, k=3, filters={"category": "guides"})
    for r in filtered:
        d = r.to_dict()
        print(f"  score={d['score']:.3f} | doc={d['doc_id']} "
              f"cat={d['metadata'].get('category')} "
              f"dept={d['metadata'].get('department')}")
    print(f"  (docs outside category 'guides' were excluded: "
          f"{[c.doc_id for c in rag.index.chunks if c.metadata['category'] != 'guides']})")

    # 3) Metadata BOOST rules re-rank among candidates
    print("-" * 78)
    print(f"QUERY (filtered category='guides' + priority>=4 boost +0.5): {q2!r}")
    boosted = rag.retrieve(
        q2,
        k=3,
        filters={"category": "guides"},
        boost_rules=[{"field": "priority", "op": "$gte", "value": 4,
                      "weight": 0.5}],
    )
    for r in boosted:
        d = r.to_dict()
        print(f"  score={d['score']:.3f} dense={d['dense_score']:.3f} "
              f"sparse={d['sparse_score']:.3f} boost={d['boost']:.3f} | "
              f"doc={d['doc_id']} priority={d['metadata'].get('priority')}")

    # 4) Grounded answer generation
    print("-" * 78)
    out = rag.ask("what chunk size should I use for document splitting",
                  k=3, filters={"category": "guides"})
    print("ANSWER:")
    print(out["answer"])
    print(f"\n(used_llm={out['used_llm']}; {len(out['sources'])} source(s) "
          f"returned; prompt template used for external LLMs)")

    # 5) Retrieval evaluation with ground truth
    print("-" * 78)
    ground_truth = [
        ("what chunk size should I use for document splitting", ["doc-1", "doc-5"]),
        ("compare pinecone weaviate chroma faiss", ["doc-2"]),
        ("how do I measure retrieval quality", ["doc-3"]),
        ("monitor a RAG system in production", ["doc-4"]),
        ("combine dense and sparse retrieval", ["doc-5"]),
    ]
    metrics = evaluate_retrieval(rag, ground_truth, k=3)
    print("RETRIEVAL EVALUATION (k=3, no filters):")
    for key, value in metrics.items():
        print(f"  {key}: {value:.3f}")

    print("=" * 78)
    print("Demo complete. Full API is documented in the module docstring.")


if __name__ == "__main__":
    _demo()

