"""Core data structures: documents, chunks, and recursive text splitting."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple

_FRONTMATTER_RE = re.compile(r"^---\s*\n(.*?)\n---\s*\n?", re.DOTALL)


@dataclass
class Chunk:
    """A retrievable unit of text that inherits its source document's metadata."""

    text: str
    metadata: Dict[str, Any]
    chunk_id: str
    doc_id: str
    chunk_index: int

    @property
    def title(self) -> str:
        return str(self.metadata.get("title", self.doc_id))

    @property
    def source(self) -> str:
        return str(self.metadata.get("source", self.doc_id))


@dataclass
class Document:
    """A source document: body text plus metadata (parsed from frontmatter)."""

    doc_id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    source_path: Optional[str] = None


# ---------------------------------------------------------------------------
# Frontmatter parsing (a small YAML-ish subset)
# ---------------------------------------------------------------------------

def _parse_scalar(value: str) -> Any:
    """Parse a scalar: int, float, bool, list, or string."""
    value = value.strip()
    if value.startswith("[") and value.endswith("]"):
        inner = value[1:-1]
        return [p.strip().strip("\"'") for p in inner.split(",") if p.strip()]
    if value.lower() in {"true", "false"}:
        return value.lower() == "true"
    if value.lower() in {"null", "none", "~"}:
        return None
    if re.fullmatch(r"-?\d+", value):
        return int(value)
    if re.fullmatch(r"-?\d+(\.\d+)?", value):
        return float(value)
    return value.strip("\"'")


def parse_frontmatter(text: str) -> Tuple[Dict[str, Any], str]:
    """Split '---' frontmatter (metadata) from the document body."""
    match = _FRONTMATTER_RE.match(text)
    if not match:
        return {}, text
    metadata: Dict[str, Any] = {}
    for line in match.group(1).splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        key, sep, raw = line.partition(":")
        if not sep:
            continue
        metadata[key.strip()] = _parse_scalar(raw)
    return metadata, text[match.end():]


def load_documents(directory: str | Path) -> List[Document]:
    """Recursively load .md/.txt/.rst documents with frontmatter metadata."""
    root = Path(directory)
    documents: List[Document] = []
    for path in sorted(root.rglob("*")):
        if not path.is_file() or path.suffix.lower() not in {".md", ".txt", ".rst", ".markdown"}:
            continue
        raw = path.read_text(encoding="utf-8")
        metadata, body = parse_frontmatter(raw)
        doc_id = str(metadata.pop("id", None) or path.stem)
        metadata.setdefault("source", str(path))
        metadata.setdefault("title", path.stem.replace("_", " ").title())
        documents.append(
            Document(doc_id=doc_id, text=body, metadata=metadata, source_path=str(path))
        )
    return documents


# ---------------------------------------------------------------------------
# Recursive character text splitting (chunking)
# ---------------------------------------------------------------------------

class RecursiveCharacterTextSplitter:
    """Splits text on a hierarchy of separators, then adds overlap.

    Separators are tried in order (double newline -> single newline ->
    sentence period -> space -> raw characters) so paragraphs and headings
    stay intact whenever possible -- the same strategy as LangChain's
    ``RecursiveCharacterTextSplitter``.
    """

    def __init__(
        self,
        chunk_size: int = 800,
        chunk_overlap: int = 120,
        separators: Optional[Sequence[str]] = None,
    ) -> None:
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = list(separators or ["\n\n", "\n", ". ", " ", ""])

    def split_text(self, text: str) -> List[str]:
        pieces = self._split_text(text, 0)
        return self._apply_overlap([p for p in pieces if p.strip()])

    def split_document(self, document: Document) -> List[Chunk]:
        return [
            Chunk(
                text=text.strip(),
                metadata=dict(document.metadata),
                chunk_id=f"{document.doc_id}:{i}",
                doc_id=document.doc_id,
                chunk_index=i,
            )
            for i, text in enumerate(self.split_text(document.text))
        ]

    def _split_text(self, text: str, sep_index: int) -> List[str]:
        if len(text) <= self.chunk_size:
            return [text] if text.strip() else []
        if sep_index >= len(self.separators):
            return self._hard_split(text)
        separator = self.separators[sep_index]
        if separator == "":
            return self._hard_split(text)
        parts = text.split(separator)
        if len(parts) <= 1:
            return self._split_text(text, sep_index + 1)
        chunks: List[str] = []
        buffer = ""
        for part in parts:
            piece = part + separator if part else ""
            if not piece:
                continue
            if len(buffer) + len(piece) <= self.chunk_size:
                buffer += piece
            else:
                if buffer:
                    chunks.append(buffer)
                if len(piece) <= self.chunk_size:
                    buffer = piece
                else:
                    buffer = ""
                    chunks.extend(self._split_text(piece, sep_index + 1))
        if buffer:
            chunks.append(buffer)
        return chunks

    def _hard_split(self, text: str) -> List[str]:
        return [text[i:i + self.chunk_size] for i in range(0, len(text), self.chunk_size)]

    def _apply_overlap(self, chunks: List[str]) -> List[str]:
        if self.chunk_overlap <= 0:
            return chunks
        result: List[str] = []
        for i, chunk in enumerate(chunks):
            if i > 0:
                tail = result[-1][-self.chunk_overlap:]
                chunk = tail + chunk
            result.append(chunk.strip())
        return result

"""Metadata filtering, hybrid relevance ranking, and retrieval.

Two retrieval stages are combined here:

1. **Filtering** -- a declarative metadata filter narrows the candidate set
   before any scoring happens (filter pushdown, the same idea as a vector DB
   applying a predicate before ANN search).
2. **Ranking** -- each surviving candidate is scored by a weighted blend of
   *BM25* (sparse lexical match), *dense cosine* (semantic match via
   ``HashEmbedding``), and an optional *metadata boost* (importance, recency,
   category authority). ``maximal marginal relevance`` (MMR) optionally
   trades a little relevance for diversity in the top-k.
"""

from __future__ import annotations

import math
from collections import Counter
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Sequence, Tuple

from .core import Chunk
from .embeddings import HashEmbedding, tokenize


# ---------------------------------------------------------------------------
# Metadata filter DSL
#
#   {"category": "engineering"}                      equality
#   {"category": ["engineering", "research"]}        membership (list overlap)
#   {"year": {"gte": 2023}}                          comparison ops
#   {"tags": {"contains": "monitoring"}}             substring / tag match
#   {"$and": [...], "$or": [...], "$not": {...}}     boolean combinators
# ---------------------------------------------------------------------------

def _matches_op(actual: Any, op: str, expected: Any) -> bool:
    if op == "eq":
        return actual == expected
    if op == "ne":
        return actual != expected
    if op == "in":
        if isinstance(actual, list):
            return any(item in expected for item in actual)
        return actual in expected
    if op in {"gte", "gt", "lte", "lt"}:
        if isinstance(actual, (int, float)) and isinstance(expected, (int, float)):
            return {
                "gte": actual >= expected,
                "gt": actual > expected,
                "lte": actual <= expected,
                "lt": actual < expected,
            }[op]
        return False
    if op == "contains":
        return expected in str(actual)
    if op == "exists":
        return actual is not None
    raise ValueError(f"Unknown filter operator: {op!r}")


def matches_filter(metadata: Dict[str, Any], flt: Optional[Dict[str, Any]]) -> bool:
    """Return True if ``metadata`` satisfies the filter dict (see DSL above)."""
    if flt is None:
        return True
    if not isinstance(flt, dict):
        raise TypeError("Filter must be a dict (see the DSL docstring)")
    if "$and" in flt:
        return all(matches_filter(metadata, f) for f in flt["$and"])
    if "$or" in flt:
        return any(matches_filter(metadata, f) for f in flt["$or"])
    if "$not" in flt:
        return not matches_filter(metadata, flt["$not"])
    for key, spec in flt.items():
        actual = metadata.get(key)
        if isinstance(spec, dict) and any(
            op in spec for op in ("eq", "ne", "in", "gte", "gt", "lte", "lt", "contains", "exists")
        ):
            for op, expected in spec.items():
                if not _matches_op(actual, op, expected):
                    return False
        elif isinstance(spec, (list, tuple, set)):
            if not _matches_op(actual, "in", list(spec)):
                return False
        elif not _matches_op(actual, "eq", spec):
            return False
    return True


# ---------------------------------------------------------------------------
# Sparse retrieval: Okapi BM25
# ---------------------------------------------------------------------------

class BM25:
    """Okapi BM25 over the tokenised corpus (sparse lexical retrieval)."""

    def __init__(self, k1: float = 1.5, b: float = 0.75):
        self.k1 = k1
        self.b = b
        self.doc_terms: List[Counter] = []
        self.doc_lengths: List[int] = []
        self.doc_freq: Counter = Counter()
        self.n_docs: int = 0
        self.avgdl: float = 1.0

    def fit(self, texts: Sequence[str]) -> "BM25":
        self.doc_terms = [Counter(tokenize(t)) for t in texts]
        self.doc_lengths = [sum(c.values()) for c in self.doc_terms]
        self.n_docs = len(texts)
        self.avgdl = sum(self.doc_lengths) / max(1, self.n_docs)
        for counter in self.doc_terms:
            self.doc_freq.update(counter.keys())
        return self

    def score(self, query: str, doc_index: int) -> float:
        counter = self.doc_terms[doc_index]
        dl = self.doc_lengths[doc_index]
        score = 0.0
        for token in set(tokenize(query)):
            tf = counter.get(token, 0)
            if tf == 0:
                continue
            idf = math.log(
                1.0 + (self.n_docs - self.doc_freq[token] + 0.5) / (self.doc_freq[token] + 0.5)
            )
            tf_component = tf * (self.k1 + 1.0) / (
                tf + self.k1 * (1.0 - self.b + self.b * dl / self.avgdl)
            )
            score += idf * tf_component
        return score


# ---------------------------------------------------------------------------
# Ranking-time metadata boosts
# ---------------------------------------------------------------------------

class MetadataBoost:
    """Optional metadata signals added to the relevance score.

    ``numeric`` fields are scaled to [0, 1] against their corpus-observed range
    (or explicit min/max); ``categorical`` fields award a fixed bonus when the
    metadata value matches. Components are summed and capped at 1.0.

    Example::

        MetadataBoost(
            numeric={"importance": {"weight": 0.20},
                     "year": {"weight": 0.10, "higher_is_better": True}},
            categorical={"category": {"operations": 0.10}},
        )
    """

    def __init__(
        self,
        numeric: Optional[Dict[str, Dict[str, Any]]] = None,
        categorical: Optional[Dict[str, Dict[Any, float]]] = None,
    ) -> None:
        self.numeric = numeric or {}
        self.categorical = categorical or {}

    def score(self, metadata: Dict[str, Any], index: Optional["ChunkIndex"] = None) -> float:
        total = 0.0
        for field, spec in self.numeric.items():
            value = metadata.get(field)
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                continue
            weight = float(spec.get("weight", 0.1))
            lo, hi = spec.get("min"), spec.get("max")
            if (lo is None or hi is None) and index is not None:
                stats = index.numeric_stats.get(field)
                if stats:
                    lo, hi = stats
            if lo is None or hi is None or hi == lo:
                continue
            scaled = (value - lo) / (hi - lo)
            if not spec.get("higher_is_better", True):
                scaled = 1.0 - scaled
            total += weight * max(0.0, min(1.0, scaled))
        for field, mapping in self.categorical.items():
            value = metadata.get(field)
            if value in mapping:
                total += mapping[value]
        return min(1.0, total)

    def summary(self) -> str:
        parts = [f"{field}={spec.get('weight')}" for field, spec in self.numeric.items()]
        parts += [f"{field}={list(mapping.values())}" for field, mapping in self.categorical.items()]
        return " + ".join(parts) or "(none)"


# ---------------------------------------------------------------------------
# Index and retriever
# ---------------------------------------------------------------------------

@dataclass
class RetrievedChunk:
    """One ranked result: the chunk plus its score breakdown."""

    chunk: Chunk
    score: float
    bm25_score: float = 0.0
    dense_score: float = 0.0
    meta_boost: float = 0.0
    chunk_index: int = -1

    @property
    def title(self) -> str:
        return self.chunk.title

    @property
    def source(self) -> str:
        return self.chunk.source


class ChunkIndex:
    """In-memory index over chunks: dense vectors, BM25 terms, metadata stats."""

    def __init__(self, chunks: Sequence[Chunk], embedding: Optional[HashEmbedding] = None):
        self.chunks = list(chunks)
        self.embedding = embedding or HashEmbedding()
        if not self.embedding.idf:  # learn corpus IDF if not already fitted
            self.embedding.fit([c.text for c in self.chunks])
        self.dense_vectors = [self.embedding.embed(c.text) for c in self.chunks]
        self._bm25 = BM25().fit([c.text for c in self.chunks])

        # Observed numeric ranges per metadata field, used by MetadataBoost.
        self.numeric_stats: Dict[str, Tuple[float, float]] = {}
        for chunk in self.chunks:
            for key, value in chunk.metadata.items():
                if isinstance(value, (int, float)) and not isinstance(value, bool):
                    lo, hi = self.numeric_stats.get(key, (value, value))
                    self.numeric_stats[key] = (min(lo, value), max(hi, value))

    def filter_chunks(self, filters: Optional[Dict[str, Any]]) -> List[Tuple[int, Chunk]]:
        return [(i, c) for i, c in enumerate(self.chunks) if matches_filter(c.metadata, filters)]


class Retriever:
    """Combines metadata filtering, hybrid ranking, metadata boosts, and MMR."""

    def __init__(
        self,
        index: ChunkIndex,
        weights: Optional[Dict[str, float]] = None,
        top_k: int = 5,
        use_mmr: bool = False,
        mmr_lambda: float = 0.7,
    ) -> None:
        self.index = index
        self.weights = dict(weights or {"bm25": 0.4, "dense": 0.4, "meta": 0.2})
        self.top_k = top_k
        self.use_mmr = use_mmr
        self.mmr_lambda = mmr_lambda

    def retrieve(
        self,
        query: str,
        filters: Optional[Dict[str, Any]] = None,
        boost: Optional[MetadataBoost] = None,
        k: Optional[int] = None,
        score_threshold: Optional[float] = None,
    ) -> List[RetrievedChunk]:
        """Filter candidates by metadata, then rank them by relevance."""
        k = k or self.top_k
        query_vec = self.index.embedding.embed(query)
        candidates = self.index.filter_chunks(filters)

        scored: List[RetrievedChunk] = []
        for i, chunk in candidates:
            bm25 = self.index._bm25.score(query, i)
            dense = max(0.0, HashEmbedding.cosine(query_vec, self.index.dense_vectors[i]))
            meta = boost.score(chunk.metadata, self.index) if boost else 0.0
            scored.append(RetrievedChunk(chunk, 0.0, bm25, dense, meta, chunk_index=i))

        # Normalise BM25 per-query so the weighted blend is comparable to cosine.
        max_bm25 = max((r.bm25_score for r in scored), default=0.0)
        if max_bm25 > 0:
            for r in scored:
                r.bm25_score /= max_bm25

        for r in scored:
            r.score = (
                self.weights.get("bm25", 0.0) * r.bm25_score
                + self.weights.get("dense", 0.0) * r.dense_score
                + self.weights.get("meta", 0.0) * r.meta_boost
            )
        scored.sort(key=lambda r: r.score, reverse=True)

        if self.use_mmr:
            scored = self._apply_mmr(scored, k)
        else:
            scored = scored[:k]
        if score_threshold is not None:
            scored = [r for r in scored if r.score >= score_threshold]
        return scored

    def _apply_mmr(self, scored: List[RetrievedChunk], k: int) -> List[RetrievedChunk]:
        """Maximal marginal relevance: reward diversity among selected chunks."""
        selected: List[RetrievedChunk] = []
        remaining = scored[:]
        while remaining and len(selected) < k:
            best: Optional[RetrievedChunk] = None
            best_value: Optional[float] = None
            for r in remaining:
                if selected:
                    redundancy = max(
                        HashEmbedding.cosine(
                            self.index.dense_vectors[r.chunk_index],
                            self.index.dense_vectors[s.chunk_index],
                        )
                        for s in selected
                    )
                else:
                    redundancy = 0.0
                value = self.mmr_lambda * r.score - (1.0 - self.mmr_lambda) * redundancy
                if best is None or value > best_value:
                    best, best_value = r, value
            selected.append(best)
            remaining.remove(best)
        return selected

"""Metadata-filtered, relevance-ranked Retrieval-Augmented Generation (RAG).

A self-contained, pure-standard-library implementation of a RAG system that:

1. Indexes documents from the local workspace (or an in-memory demo corpus).
2. Splits them into chunks (recursive, with configurable size/overlap).
3. Builds both a sparse index (BM25 keyword statistics) and a dense index
   (deterministic feature-hashed embeddings with L2-normalized vectors).
4. Retrieves chunks under arbitrary *metadata filters* (AND of field
   predicates: equality, in/contains, numeric ranges, regex, existence).
5. Ranks candidates by relevance using one of four strategies:
     - "bm25"         : classic BM25 keyword match
     - "cosine"       : cosine similarity over hashed embeddings
     - "hybrid"       : weighted BM25 + cosine
     - "hybrid_meta"  : hybrid plus a metadata-affinity bonus (docs whose
                        metadata values match query terms rank higher)
6. Supports Maximal Marginal Relevance (MMR) for diverse result sets.
7. Generates a grounded, citation-tagged answer with a confidence score,
   or explicitly reports insufficient information when retrieval is weak.
8. Evaluates retrieval quality (recall@k, precision@k, MRR) and answer
   groundedness (n-gram overlap between answer and retrieved context).

Everything runs locally with no external services, no API keys, and no
third-party packages (Python >= 3.8, standard library only).

Quick start (from this file's directory):

    python rag_metadata_rag.py --query "how do I choose a chunk size?"
    python rag_metadata_rag.py --query "metadata filter gte lte" \
        --filters '{"category": "faq"}'
    python rag_metadata_rag.py --docs ./data/docs --eval

Example metadata filter predicates (JSON):

    {"category": "faq"}
    {"year": {"gte": 2024, "lte": 2025}}
    {"tags": {"contains": "reranking"}}
    {"author": {"regex": "^data"}}
    {"deleted": {"exists": False}}
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import re
import sys
from collections import Counter
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable, Dict, Iterable, List, Optional, Sequence, Tuple

# --------------------------------------------------------------------------- #
# Tokenization helpers
# --------------------------------------------------------------------------- #

_TOKEN_RE = re.compile(r"[a-z0-9]+")


def tokenize(text: str) -> List[str]:
    """Lowercase alphanumeric tokenization of arbitrary text."""
    if not text:
        return []
    return _TOKEN_RE.findall(str(text).lower())


def _mean(xs: Sequence[float]) -> float:
    return sum(xs) / len(xs) if xs else 0.0


# --------------------------------------------------------------------------- #
# Document / chunk dataclasses
# --------------------------------------------------------------------------- #


@dataclass
class Document:
    """A source document plus its metadata."""

    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    doc_id: str = ""
    source: str = ""


@dataclass
class Chunk:
    """A retrievable unit cut from a source document."""

    chunk_id: str
    doc_id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    position: int = 0
    source: str = ""


@dataclass
class RetrievedChunk:
    """A chunk returned by the retriever with its relevance breakdown."""

    chunk: Chunk
    score: float
    components: Dict[str, float] = field(default_factory=dict)


@dataclass
class AnswerResult:
    """Grounded answer plus citations and retrieval evidence."""

    query: str
    answer: str
    confidence: float
    sources: List[Dict[str, Any]]
    results: List[RetrievedChunk]

    def to_dict(self) -> Dict[str, Any]:
        return {
            "query": self.query,
            "answer": self.answer,
            "confidence": round(self.confidence, 4),
            "sources": self.sources,
        }


# --------------------------------------------------------------------------- #
# Chunking
# --------------------------------------------------------------------------- #


def _split_units(text: str, separators: Sequence[str]) -> List[str]:
    """Split text on the given separators, keeping separators attached."""
    seps = [s for s in (separators or ()) if s]
    if not seps:
        return [text]
    pattern = "|".join(re.escape(s) for s in seps)
    parts = re.split(r"(" + pattern + r")", text)
    units: List[str] = []
    for i in range(0, len(parts), 2):
        piece = parts[i]
        if i + 1 < len(parts):
            piece += parts[i + 1]
        if piece.strip():
            units.append(piece)
    return units


def _tail_window(text: str, n: int) -> str:
    """Last n characters, trimmed back to a word boundary when possible."""
    if len(text) <= n:
        return text
    tail = text[-n:]
    cut = tail.find(" ")
    if 0 < cut < len(tail) // 2:
        tail = tail[cut:].strip()
    return tail


def chunk_text(
    text: str,
    chunk_size: int = 900,
    chunk_overlap: int = 180,
    separators: Sequence[str] = ("\n\n", "\n", ". ", " "),
) -> List[str]:
    """Recursively chunk text into overlapping pieces of at most chunk_size."""
    if chunk_size <= 0:
        raise ValueError("chunk_size must be > 0")
    text = (text or "").strip()
    if not text:
        return []
    chunk_overlap = max(0, min(chunk_overlap, chunk_size - 1))
    step = max(1, chunk_size - chunk_overlap)

    units = _split_units(text, separators)
    chunks: List[str] = []
    current = ""
    for unit in units:
        if len(unit) > chunk_size:
            if current:
                chunks.append(current)
                current = ""
            for i in range(0, len(unit), step):
                piece = unit[i : i + chunk_size].strip()
                if piece:
                    chunks.append(piece)
            continue
        if current and len(current) + 1 + len(unit) > chunk_size:
            chunks.append(current)
            current = _tail_window(current, chunk_overlap)
        current = current + "\n" + unit if current else unit
    if current:
        chunks.append(current)

    # Fold a tiny trailing chunk back into its predecessor when it fits.
    if len(chunks) >= 2 and len(chunks[-1]) <= chunk_overlap:
        if len(chunks[-2]) + 1 + len(chunks[-1]) <= chunk_size:
            chunks[-2] = chunks[-2] + "\n" + chunks[-1]
            chunks.pop()
    return chunks


class Chunker:
    """Configurable recursive text splitter bound to a chunk strategy."""

    def __init__(
        self,
        chunk_size: int = 900,
        chunk_overlap: int = 180,
        separators: Sequence[str] = ("\n\n", "\n", ". ", " "),
    ) -> None:
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = tuple(separators)

    def chunk_document(self, doc: Document) -> List[str]:
        return chunk_text(doc.text, self.chunk_size, self.chunk_overlap, self.separators)

    def __call__(self, doc: Document) -> List[str]:
        return self.chunk_document(doc)


# --------------------------------------------------------------------------- #
# Dense embeddings (deterministic feature hashing, no external model)
# --------------------------------------------------------------------------- #


class HashEmbedding:
    """Feature-hashed bag-of-words vectors with L2 normalization.

    Each token maps deterministically (via SHA-256) to one of ``dim`` feature
    indices with a +/- sign, weighted by term frequency. The resulting vectors
    support cosine similarity and are stable across processes, so an index can
    be persisted and re-queried without re-embedding.
    """

    def __init__(self, dim: int = 512) -> None:
        if dim < 8:
            raise ValueError("embedding dimension must be >= 8")
        self.dim = dim

    def embed(self, text: str) -> List[float]:
        vec = [0.0] * self.dim
        for tok in tokenize(text):
            digest = hashlib.sha256(tok.encode("utf-8")).digest()
            idx = int.from_bytes(digest[:4], "big") % self.dim
            sign = 1.0 if (digest[4] & 1) else -1.0
            vec[idx] += sign
        norm = math.sqrt(sum(v * v for v in vec))
        if norm == 0.0:
            return vec
        return [v / norm for v in vec]

    @staticmethod
    def cosine(a: Sequence[float], b: Sequence[float]) -> float:
        return sum(x * y for x, y in zip(a, b))


# --------------------------------------------------------------------------- #
# Sparse ranking: BM25
# --------------------------------------------------------------------------- #


class BM25:
    """Classic Okapi BM25 term-weighting over a fixed set of documents."""

    def __init__(self, k1: float = 1.5, b: float = 0.75) -> None:
        self.k1 = k1
        self.b = b
        self.doc_ids: List[str] = []
        self.doc_freq: Counter = Counter()
        self.doc_tokens: Dict[str, Counter] = {}
        self.doc_length: Dict[str, int] = {}
        self.total_terms = 0
        self.doc_count = 0
        self.avgdl = 0.0
        self.ready = False

    def add_document(self, doc_id: str, tokens: Sequence[str]) -> None:
        self.doc_ids.append(doc_id)
        tf = Counter(tokens)
        self.doc_tokens[doc_id] = tf
        self.doc_length[doc_id] = len(tokens)
        self.total_terms += len(tokens)
        for term in tf:
            self.doc_freq[term] += 1
        self.ready = False

    def finalize(self) -> None:
        n = len(self.doc_ids)
        self.doc_count = n
        self.avgdl = self.total_terms / n if n else 0.0
        self.ready = True

    def idf(self, term: str) -> float:
        n = self.doc_freq.get(term, 0)
        N = self.doc_count
        return math.log(1.0 + (N - n + 0.5) / (n + 0.5))

    def score(self, query_tokens: Sequence[str], doc_id: str) -> float:
        tf = self.doc_tokens.get(doc_id)
        if not tf:
            return 0.0
        dl = self.doc_length.get(doc_id, 0)
        length_norm = 1.0 - self.b + self.b * (dl / self.avgdl if self.avgdl else 1.0)
        total = 0.0
        for term in set(query_tokens):
            f = tf.get(term, 0)
            if f == 0:
                continue
            total += self.idf(term) * (f * (self.k1 + 1.0)) / (f + self.k1 * length_norm)
        return total


# --------------------------------------------------------------------------- #
# Metadata filtering
# --------------------------------------------------------------------------- #


def _equal(a: Any, b: Any) -> bool:
    if a is None or b is None:
        return a is b
    if isinstance(a, bool) or isinstance(b, bool):
        return a is b
    if type(a) is not type(b):
        try:
            return float(a) == float(b)
        except (TypeError, ValueError):
            pass
    if isinstance(a, str) and isinstance(b, str):
        return a.lower() == b.lower()
    return a == b


def _to_num(value: Any) -> Optional[float]:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(str(value))
    except (TypeError, ValueError):
        return None


def _satisfies(value: Any, pred: Any) -> bool:
    """Test a single metadata value against one predicate specification."""
    if isinstance(pred, dict):
        for op, operand in pred.items():
            op = str(op).lower()
            if op == "eq":
                if not _equal(value, operand):
                    return False
            elif op == "ne":
                if _equal(value, operand):
                    return False
            elif op in ("in", "contains"):
                if value is None:
                    return False
                if isinstance(operand, (list, tuple, set)):
                    if isinstance(value, (list, tuple, set)):
                        if not (set(value) & set(operand)):
                            return False
                    elif value not in operand:
                        return False
                else:
                    if isinstance(value, (list, tuple, set)):
                        if operand not in value:
                            return False
                    elif operand not in str(value):
                        return False
            elif op == "not_in":
                if value is None:
                    continue
                if isinstance(operand, (list, tuple, set)):
                    if isinstance(value, (list, tuple, set)):
                        if set(value) & set(operand):
                            return False
                    elif value in operand:
                        return False
            elif op in ("gte", "gt", "lte", "lt"):
                nv = _to_num(value)
                no = _to_num(operand)
                if nv is None or no is None:
                    return False
                if op == "gte" and nv < no:
                    return False
                if op == "gt" and nv <= no:
                    return False
                if op == "lte" and nv > no:
                    return False
                if op == "lt" and nv >= no:
                    return False
            elif op == "regex":
                if value is None or not re.search(str(operand), str(value)):
                    return False
            elif op == "exists":
                if bool(operand) != (value is not None):
                    return False
            else:
                raise ValueError(f"Unsupported metadata predicate operator: {op}")
        return True

    if isinstance(pred, (list, tuple, set)):
        if value is None:
            return False
        if isinstance(value, (list, tuple, set)):
            return bool(set(value) & set(pred))
        return value in pred
    return _equal(value, pred)


class MetadataFilter:
    """A conjunction of field predicates over document metadata."""

    def __init__(self, predicates: Optional[Dict[str, Any]] = None) -> None:
        self.predicates = dict(predicates or {})

    def matches(self, metadata: Dict[str, Any]) -> bool:
        for key, pred in self.predicates.items():
            if not _satisfies(metadata.get(key), pred):
                return False
        return True


def _normalize(scores: Dict[str, float]) -> Dict[str, float]:
    if not scores:
        return {}
    top = max(scores.values())
    if top <= 0.0:
        return {key: 0.0 for key in scores}
    return {key: val / top for key, val in scores.items()}


# --------------------------------------------------------------------------- #
# Corpus index
# --------------------------------------------------------------------------- #


class CorpusIndex:
    """Owns the chunk list, BM25 statistics, and per-chunk dense vectors."""

    def __init__(self, chunker: Optional[Chunker] = None, embedder: Optional[HashEmbedding] = None) -> None:
        self.chunker = chunker or Chunker()
        self.embedder = embedder or HashEmbedding()
        self.bm25 = BM25()
        self.chunks: List[Chunk] = []
        self.chunk_by_id: Dict[str, Chunk] = {}
        self.vectors: Dict[str, List[float]] = {}

    def add_document(self, doc: Document) -> int:
        pieces = self.chunker.chunk_document(doc)
        for i, text in enumerate(pieces):
            chunk = Chunk(
                chunk_id=f"{doc.doc_id or 'doc'}#{i}",
                doc_id=doc.doc_id,
                text=text,
                metadata=dict(doc.metadata),
                position=i,
                source=doc.source,
            )
            self._add_chunk(chunk)
        return len(pieces)

    def _add_chunk(self, chunk: Chunk) -> None:
        self.chunks.append(chunk)
        self.chunk_by_id[chunk.chunk_id] = chunk
        toks = tokenize(chunk.text)
        self.bm25.add_document(chunk.chunk_id, toks)
        self.vectors[chunk.chunk_id] = self.embedder.embed(chunk.text)

    def finalize(self) -> None:
        self.bm25.finalize()

    @property
    def size(self) -> int:
        return len(self.chunks)


# --------------------------------------------------------------------------- #
# Retrieval: metadata filtering + relevance ranking
# --------------------------------------------------------------------------- #


def _metadata_affinity(query: str, metadata: Dict[str, Any]) -> float:
    """Fraction of query tokens that appear in any metadata value."""
    q_toks = set(tokenize(query))
    if not q_toks:
        return 0.0
    hits = 0
    for value in metadata.values():
        if value is None:
            continue
        if isinstance(value, (list, tuple, set)):
            values = [str(v) for v in value]
        else:
            values = [str(value)]
        v_toks = set(tokenize(" ".join(values)))
        hits += len(q_toks & v_toks)
    return hits / len(q_toks)


class Retriever:
    """Filters candidate chunks by metadata, then ranks them by relevance."""

    STRATEGIES = ("bm25", "cosine", "hybrid", "hybrid_meta")

    def __init__(self, index: CorpusIndex, alpha: float = 0.6, meta_weight: float = 0.3) -> None:
        self.index = index
        self.alpha = alpha  # BM25 share of the hybrid relevance score
        self.meta_weight = meta_weight  # metadata-affinity bonus share

    def retrieve(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Dict[str, Any]] = None,
        strategy: str = "hybrid_meta",
        diversity: float = 0.0,
        fetch_k: Optional[int] = None,
        min_score: float = 0.0,
    ) -> List[RetrievedChunk]:
        if strategy not in self.STRATEGIES:
            raise ValueError(f"Unknown strategy {strategy!r}; choose from {self.STRATEGIES}")
        if not self.index.bm25.ready:
            self.index.finalize()

        q_toks = tokenize(query)
        q_vec = self.index.embedder.embed(query)
        filter_obj = filters if isinstance(filters, MetadataFilter) else MetadataFilter(filters or {})

        candidates = [c for c in self.index.chunks if filter_obj.matches(c.metadata)]

        bm25_raw: Dict[str, float] = {}
        cos_raw: Dict[str, float] = {}
        meta_raw: Dict[str, float] = {}
        for c in candidates:
            bm25_raw[c.chunk_id] = self.index.bm25.score(q_toks, c.chunk_id)
            cos_raw[c.chunk_id] = HashEmbedding.cosine(q_vec, self.index.vectors[c.chunk_id])
            meta_raw[c.chunk_id] = _metadata_affinity(query, c.metadata)

        bm25_n = _normalize(bm25_raw)
        cos_n = _normalize(cos_raw)
        meta_n = _normalize(meta_raw)

        combined: Dict[str, float] = {}
        for c in candidates:
            cid = c.chunk_id
            if strategy == "bm25":
                score = bm25_n[cid]
            elif strategy == "cosine":
                score = max(cos_n[cid], 0.0)
            elif strategy == "hybrid":
                score = self.alpha * bm25_n[cid] + (1.0 - self.alpha) * max(cos_n[cid], 0.0)
            else:  # hybrid_meta
                relevance = self.alpha * bm25_n[cid] + (1.0 - self.alpha) * max(cos_n[cid], 0.0)
                score = (1.0 - self.meta_weight) * relevance + self.meta_weight * meta_n[cid]
            combined[cid] = score

        ranked = sorted(candidates, key=lambda c: combined[c.chunk_id], reverse=True)
        fetch = max(fetch_k or k, k)
        top = ranked[:fetch]

        if diversity > 0.0 and k > 1:
            top = self._mmr_select(q_vec, top, k, diversity)

        results: List[RetrievedChunk] = []
        for c in top[:k]:
            results.append(
                RetrievedChunk(
                    chunk=c,
                    score=combined[c.chunk_id],
                    components={
                        "bm25": bm25_raw[c.chunk_id],
                        "cosine": cos_raw[c.chunk_id],
                        "metadata_affinity": meta_raw[c.chunk_id],
                    },
                )
            )
        if min_score > 0.0:
            results = [r for r in results if r.score >= min_score]
        return results

    def _mmr_select(
        self, q_vec: List[float], candidates: Sequence[Chunk], k: int, lambda_mult: float
    ) -> List[Chunk]:
        """Maximal Marginal Relevance: relevance minus redundancy."""
        selected: List[Chunk] = []
        remaining = list(candidates)
        for _ in range(min(k, len(remaining))):
            best: Optional[Chunk] = None
            best_val = -math.inf
            for c in remaining:
                relevance = HashEmbedding.cosine(q_vec, self.index.vectors[c.chunk_id])
                if selected:
                    redundancy = max(
                        HashEmbedding.cosine(
                            self.index.vectors[c.chunk_id],
                            self.index.vectors[s.chunk_id],
                        )
                        for s in selected
                    )
                else:
                    redundancy = 0.0
                value = lambda_mult * relevance - (1.0 - lambda_mult) * redundancy
                if value > best_val:
                    best_val = value
                    best = c
            if best is None:
                break
            selected.append(best)
            remaining.remove(best)
        return selected


# --------------------------------------------------------------------------- #
# Grounded generation (extractive, with citations and confidence)
# --------------------------------------------------------------------------- #

_SENT_SPLIT = re.compile(r"(?<=[.!?])\s+|\n+")


def _split_sentences(text: str) -> List[str]:
    return [s.strip() for s in _SENT_SPLIT.split(text or "") if s.strip()]


class GroundedGenerator:
    """Builds a citation-tagged answer from retrieved chunks.

    Because this workspace artifact runs without an external LLM, generation
    is *extractive*: the best query-overlapping sentence is selected from each
    retrieved chunk and attributed with a bracketed citation. The prompt-level
    contract is identical to LLM-based RAG: answer only from retrieved
    context, and emit "insufficient information" when evidence is weak.
    """

    def __init__(self, max_sentences: int = 3, min_score: float = 0.05) -> None:
        self.max_sentences = max_sentences
        self.min_score = min_score

    def generate(self, query: str, results: Sequence[RetrievedChunk], min_score: Optional[float] = None) -> Optional[AnswerResult]:
        threshold = self.min_score if min_score is None else min_score
        if not results or results[0].score < threshold:
            return None

        q_toks = set(tokenize(query))
        picks: List[Tuple[int, str, RetrievedChunk]] = []
        for idx, r in enumerate(results, start=1):
            best_overlap = 0.0
            best_sentence = ""
            for sentence in _split_sentences(r.chunk.text):
                overlap = len(q_toks & set(tokenize(sentence)))
                if overlap > best_overlap:
                    best_overlap = overlap
                    best_sentence = sentence
            if best_sentence:
                picks.append((idx, best_sentence, r))

        parts: List[str] = []
        seen: set = set()
        for idx, sentence, r in picks:
            signature = tuple(tokenize(sentence)[:8])
            if signature in seen:
                continue
            seen.add(signature)
            parts.append(f"{sentence} [{idx}]")
            if len(parts) >= self.max_sentences:
                break

        if not parts:
            answer = (
                "Based on the retrieved context, I cannot extract a confident answer. "
                f"[1] (lowest-confidence fallback; sources: {len(results)} chunks)"
            )
        else:
            answer = " ".join(parts)

        confidence = min(0.99, 0.5 + 0.5 * results[0].score)
        sources = [
            {
                "rank": i + 1,
                "chunk_id": r.chunk.chunk_id,
                "doc_id": r.chunk.doc_id,
                "source": r.chunk.source,
                "score": round(r.score, 4),
                "components": {key: round(val, 4) for key, val in r.components.items()},
                "metadata": r.chunk.metadata,
            }
            for i, r in enumerate(results)
        ]
        return AnswerResult(query=query, answer=answer, confidence=confidence, sources=sources, results=list(results))


# --------------------------------------------------------------------------- #
# High-level facade
# --------------------------------------------------------------------------- #


class MetadataRAG:
    """End-to-end RAG: index -> filter -> rank -> grounded answer."""

    def __init__(
        self,
        chunker: Optional[Chunker] = None,
        embedder: Optional[HashEmbedding] = None,
        alpha: float = 0.6,
        meta_weight: float = 0.3,
    ) -> None:
        self.index = CorpusIndex(chunker=chunker, embedder=embedder)
        self.retriever = Retriever(self.index, alpha=alpha, meta_weight=meta_weight)
        self.generator = GroundedGenerator()
        self.documents: List[Document] = []

    # -- indexing ---------------------------------------------------------- #
    def add_document(self, doc: Document) -> int:
        self.documents.append(doc)
        return self.index.add_document(doc)

    def add_documents(self, docs: Iterable[Document]) -> int:
        total = 0
        for doc in docs:
            total += self.add_document(doc)
        self.index.finalize()
        return total

    def build(self, docs: Iterable[Document]) -> int:
        return self.add_documents(docs)

    def summary(self) -> Dict[str, Any]:
        return {
            "documents": len(self.documents),
            "chunks": self.index.size,
            "vocabulary_terms": len(self.index.bm25.doc_freq),
            "embedding_dim": self.index.embedder.dim,
        }

    # -- retrieval --------------------------------------------------------- #
    def retrieve(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Dict[str, Any]] = None,
        strategy: str = "hybrid_meta",
        diversity: float = 0.0,
        min_score: float = 0.0,
    ) -> List[RetrievedChunk]:
        return self.retriever.retrieve(
            query, k=k, filters=filters, strategy=strategy, diversity=diversity, min_score=min_score
        )

    # -- generation -------------------------------------------------------- #
    def answer(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Dict[str, Any]] = None,
        strategy: str = "hybrid_meta",
        diversity: float = 0.0,
        min_score: Optional[float] = None,
    ) -> AnswerResult:
        results = self.retrieve(query, k=k, filters=filters, strategy=strategy, diversity=diversity)
        return self.generator.generate(query, results, min_score=min_score)

    # -- persistence ------------------------------------------------------- #
    def save(self, path: str) -> None:
        payload = {
            "version": 1,
            "chunker": {
                "chunk_size": self.index.chunker.chunk_size,
                "chunk_overlap": self.index.chunker.chunk_overlap,
                "separators": list(self.index.chunker.separators),
            },
            "embedder": {"dim": self.index.embedder.dim},
            "documents": [
                {
                    "doc_id": d.doc_id,
                    "text": d.text,
                    "metadata": d.metadata,
                    "source": d.source,
                }
                for d in self.documents
            ],
        }
        Path(path).write_text(json.dumps(payload, indent=2), encoding="utf-8")

    def load(self, path: str) -> "MetadataRAG":
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
        chunker = Chunker(**payload["chunker"])
        embedder = HashEmbedding(dim=payload["embedder"]["dim"])
        self.index = CorpusIndex(chunker=chunker, embedder=embedder)
        self.retriever = Retriever(self.index)
        self.generator = GroundedGenerator()
        self.documents = []
        docs = [
            Document(
                text=d["text"],
                metadata=d.get("metadata", {}),
                doc_id=d.get("doc_id", ""),
                source=d.get("source", ""),
            )
            for d in payload["documents"]
        ]
        self.build(docs)
        return self


# --------------------------------------------------------------------------- #
# Evaluation
# --------------------------------------------------------------------------- #


def evaluate_retrieval(
    rag: MetadataRAG,
    cases: Sequence[Tuple[str, Sequence[str]]],
    k: int = 5,
    strategy: str = "hybrid_meta",
    filters: Optional[Dict[str, Any]] = None,
) -> Dict[str, float]:
    """Measure recall@k, precision@k, and MRR over (query, relevant doc ids)."""
    recalls: List[float] = []
    precisions: List[float] = []
    reciprocal_ranks: List[float] = []
    for query, relevant in cases:
        relevant_ids = set(relevant)
        results = rag.retrieve(query, k=k, strategy=strategy, filters=filters)
        retrieved = [r.chunk.doc_id for r in results]
        hits = [did for did in retrieved if did in relevant_ids]
        recalls.append(len(hits) / len(relevant_ids) if relevant_ids else 1.0)
        precisions.append(len(hits) / k if k else 0.0)
        for rank, doc_id in enumerate(retrieved, start=1):
            if doc_id in relevant_ids:
                reciprocal_ranks.append(1.0 / rank)
                break
        else:
            reciprocal_ranks.append(0.0)
    return {
        "n_cases": len(cases),
        "k": k,
        "recall_at_k": round(_mean(recalls), 4),
        "precision_at_k": round(_mean(precisions), 4),
        "mrr": round(_mean(reciprocal_ranks), 4),
    }


def groundedness(answer: str, contexts: Sequence[str]) -> float:
    """Fraction of answer tokens that appear in the supporting context."""
    answer_toks = tokenize(answer)
    if not answer_toks:
        return 1.0
    context_toks = set(tokenize(" ".join(contexts)))
    matched = sum(1 for tok in answer_toks if tok in context_toks)
    return matched / len(answer_toks)


