def _default_metadata(path: Path) -> Dict[str, Any]:
    """Heuristic metadata for a local markdown file."""
    meta: Dict[str, Any] = {"source": str(path)}
    parts = path.parts
    if len(parts) >= 2:
        meta["category"] = parts[-2]
    date_match = re.search(r"(\d{4})[-_]?(\d{2})?[-_]?(\d{2})?", path.stem)
    if date_match:
        meta["year"] = int(date_match.group(1))
    keywords = {
        "chunk": "chunking",
        "vector": "vector-db",
        "filter": "filtering",
        "rank": "ranking",
        "monitor": "monitoring",
        "eval": "evaluation",
    }
    tags = []
    lowered = path.stem.lower()
    for key, tag in keywords.items():
        if key in lowered:
            tags.append(tag)
    if tags:
        meta["tags"] = tags
    return meta


def load_documents(
    directory: str,
    pattern: str = "**/*.md",
    metadata_extractor: Optional[Callable[[Path], Dict[str, Any]]] = None,
) -> List[Document]:
    """Load local markdown/text files from a workspace directory."""
    root = Path(directory)
    if not root.is_dir():
        raise FileNotFoundError(f"Document directory not found: {directory}")
    docs: List[Document] = []
    for path in sorted(root.glob(pattern)):
        if not path.is_file():
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        meta = metadata_extractor(path) if metadata_extractor else _default_metadata(path)
        try:
            relative = str(path.relative_to(root))
        except ValueError:
            relative = path.name
        docs.append(Document(text=text, metadata=meta, doc_id=relative, source=str(path)))
    return docs


