def _print_answer(result: AnswerResult) -> None:
    print("\n=== Grounded answer ===")
    print(result.answer)
    print(f"\nConfidence: {result.confidence:.3f}")
    print("\n=== Sources (ranked) ===")
    for source in result.sources:
        print(
            f"  [{source['rank']}] {source['doc_id']} "
            f"(score={source['score']}, bm25={source['components']['bm25']:.3f}, "
            f"cosine={source['components']['cosine']:.3f}, "
            f"meta={source['components']['metadata_affinity']:.3f})"
        )
        if source["metadata"]:
            print(f"      metadata: {source['metadata']}")


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        description="Metadata-filtered, relevance-ranked RAG system (offline, stdlib only)."
    )
    parser.add_argument("--docs", default=None, help="Directory of local documents to index (default: demo corpus)")
    parser.add_argument("--pattern", default="**/*.md", help="Glob pattern when --docs is used")
    parser.add_argument("--query", default="How do I choose a chunk size and overlap?", help="Query to answer")
    parser.add_argument("--filters", default=None, help='JSON metadata filter, e.g. \'{"category": "faq"}\'')
    parser.add_argument("--k", type=int, default=5, help="Number of chunks to retrieve")
    parser.add_argument(
        "--strategy", default="hybrid_meta", choices=Retriever.STRATEGIES, help="Ranking strategy"
    )
    parser.add_argument("--diversity", type=float, default=0.0, help="MMR diversity in [0,1] (0 = off)")
    parser.add_argument("--min-score", type=float, default=None, help="Reject answers below this confidence basis")
    parser.add_argument("--eval", action="store_true", help="Run built-in retrieval evaluation instead of answering")
    parser.add_argument("--save", default=None, help="Persist the built index to a JSON file")
    parser.add_argument("--load", default=None, help="Load a previously saved index from a JSON file")
    args = parser.parse_args(argv)

    rag = MetadataRAG()
    if args.load:
        rag.load(args.load)
        print(f"Loaded index from {args.load}: {rag.summary()}")
    else:
        if args.docs:
            docs = load_documents(args.docs, pattern=args.pattern)
            print(f"Loaded {len(docs)} documents from {args.docs}")
        else:
            docs = build_demo_corpus()
            print("Using built-in demo corpus (8 curated documents).")
        n_chunks = rag.build(docs)
        print(f"Indexed {len(docs)} documents into {n_chunks} chunks.")
        if args.save:
            rag.save(args.save)
            print(f"Saved index to {args.save}")

    filters = json.loads(args.filters) if args.filters else None
    if filters is not None:
        print(f"Active metadata filter: {filters}")

    if args.eval:
        metrics = evaluate_retrieval(
            rag, demo_eval_cases(), k=args.k, strategy=args.strategy, filters=filters
        )
        print("\n=== Retrieval evaluation ===")
        print(json.dumps(metrics, indent=2))
        return 0

    result = rag.answer(
        args.query,
        k=args.k,
        filters=filters,
        strategy=args.strategy,
        diversity=args.diversity,
        min_score=args.min_score,
    )
    if result is None:
        print("\n=== Grounded answer ===")
        print("I don't have enough information to answer from the retrieved context.")
        return 0
    _print_answer(result)

    contexts = [r.chunk.text for r in result.results]
    print(f"\nAnswer groundedness (n-gram overlap with sources): {groundedness(result.answer, contexts):.3f}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
